import { cacheTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: number
}

// Simple in-memory store for demonstration
const posts: Post[] = []

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return [...posts]
}

export function addPost(post: Post): void {
  posts.push(post)
}
